sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
layout(color) uniform half4 color;
half4 main(float2 xy) {
    half4 c = image.eval(xy);
    half k = half(clamp(strength * beat, 0.0, 1.0)) * color.a;
    return half4(mix(c.rgb, color.rgb * c.a, k), c.a);
}
